mapper.select:
/* selectErrorDetail - Lee JiSeob */
SELECT C.LOG_MNG_NO, C.URL_ADDR, C.CLSSA_NM, C.METHDA_NM, C.ERR_MSSAGE_CN, C.METHDA_CALL_LIST_CN, C.MENU_NM, C.UP_MENU_NM, C.PROGRM_ID, C.DMND_IP_ADDR, C.FORMDA_CN AS FORM_DATA, C.FRST_RGTR_ID, (SELECT C##RG.DEC_B64(E.FLNM_ENCPT) FROM SAA200 D, SCA100 E WHERE D.ENFSN_NO = E.ENFSN_NO AND D.USER_ID = C.FRST_RGTR_ID) AS FRST_RGTR_NM, TO_CHAR(C.FRST_REG_DT, 'YYYY-MM-DD HH24:MI:SS') AS FRST_REG_DT, C.LAST_MDFR_ID, TO_CHAR(C.LAST_MDFCN_DT, 'YYYY-MM-DD HH24:MI:SS') AS LAST_MDFCN_DT
FROM SAB910 C /* 오류로그 */
WHERE C.LOG_MNG_NO = #{LOG_MNG_NO}
